CREATE TABLE cliente (
  id     INT PRIMARY KEY,
  nombre VARCHAR(50),
  correo VARCHAR(80)
);

CREATE TABLE pedido (
  id         INT PRIMARY KEY,
  cliente_id INT REFERENCES cliente(id),
  fecha      DATE,
  total      DECIMAL(10,2)
);

CREATE TABLE usuarios (
  id     INT PRIMARY KEY,
  nombre VARCHAR(50),
  edad   INT,
  ciudad VARCHAR(50)
);

SELECT nombre, edad
FROM usuarios
WHERE ciudad = 'Guatemala';

UPDATE usuarios
SET edad = 23
WHERE id = 1;

INSERT INTO usuarios (nombre, edad, ciudad)
VALUES ('Pedro', 27, 'Cobán');

